-- The fake clock: timers, sleeps, frames, events, patch points and deferred results.
local combat = require("game.combat")

describe("clock", function()
    it("advance fires timers in order (ok)", function()
        local log = {}
        rhp.after(300, function() log[#log + 1] = "b" .. test.now() end)
        rhp.after(100, function() log[#log + 1] = "a" .. test.now() end)
        local start = test.now()
        test.advance(250)
        assert.same({ "a" .. (start + 100) }, log)
        test.advance(50)
        assert.same({ "a" .. (start + 100), "b" .. (start + 300) }, log)
    end)

    it("an every timer and a lib call from it (ok)", function()
        combat.start()
        test.advance(2500)
        assert.equals(2, combat.rounds)
        assert.equals(0, arena.count())
        test.advance(500)
        assert.equals(3, combat.rounds)
        assert.equals(1, arena.count())
        combat.stop()
    end)

    it("the timer and the spawn are undone after the test (ok)", function()
        assert.equals(0, arena.count())
        assert.is_nil(test.next_due())
    end)

    it("frames run frame callbacks (ok)", function()
        local n = 0
        rhp.every_frame(function() n = n + 1 end)
        test.frames(3)
        assert.equals(3, n)
        local before = test.now()
        test.frames(2, { dt = 16 })
        assert.equals(5, n)
        assert.equals(before + 32, test.now())
    end)

    it("run_pending and run_all (ok)", function()
        local hits = 0
        rhp.after(10, function() hits = hits + 1 end)
        rhp.after(20, function()
            hits = hits + 1
            rhp.after(1000, function() hits = hits + 10 end)
        end)
        assert.equals(2, test.run_pending())
        assert.equals(2, hits)
        assert.equals(1, test.run_all())
        assert.equals(12, hits)
    end)

    it("a test that sleeps moves the clock (ok)", function()
        local start = test.now()
        rhp.sleep(5000)
        assert.equals(start + 5000, test.now())
    end)

    it("os.time follows the fake clock (ok)", function()
        local t = os.time()
        test.advance(3000)
        assert.equals(t + 3, os.time())
    end)

    it("events published and fired (ok)", function()
        local got = {}
        rhp.on("game.hit", function(n) got[#got + 1] = n end)
        test.publish("game.hit", 5)
        assert.same({ 5 }, got)
        local rounds = {}
        rhp.on("rhp_test.round_over", function(team) rounds[#rounds + 1] = team end)
        test.fire("rhp_test.round_over", "red")
        test.frames(1)
        assert.same({ "red" }, rounds)
    end)

    it("patch points (ok)", function()
        assert.equals(20, test.call_point("rhp_test.damage", 10, 2))
        rhp.patch("rhp_test.damage", function(original, base, target) return original(base, target) - 8 end)
        assert.equals(12, test.call_point("rhp_test.damage", 10, 2))
    end)

    it("patches are undone (ok)", function()
        assert.equals(20, test.call_point("rhp_test.damage", 10, 2))
    end)

    it("deferred results (ok)", function()
        local d = test.deferred()
        local got
        rhp.spawn(function() got = d:await() end)
        test.frames(2)
        assert.is_nil(got)
        d:resolve(42)
        test.frames(2)
        assert.equals(42, got)
    end)

    it("output and emitted (ok)", function()
        print("hello from a test")
        rhp.emit({ score = 3 })
        assert.same({ "hello from a test" }, test.output())
        assert.same({ { score = 3 } }, test.emitted())
    end)

    it("handler failures are visible (ok)", function()
        rhp.on("game.bad", function() error("handler broke") end)
        test.publish("game.bad")
        local f = test.failures()
        assert.equals(1, #f)
        assert.matches("handler broke", f[1].message)
    end)

    it("an endless timer loop is reported by run_all (fails)", function()
        rhp.every(10, function() end)
        test.run_all({ limit = 5 })
    end)

    it("waiting forever on nothing (errors)", function()
        local d = test.deferred()
        d:await()
    end)
end)
